package com.fooddelivery.delivery;
import com.fooddelivery.delivery.service.DeliveryService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
@RestController public class DeliveryController {
 private final DeliveryService service;private final String internalKey;public DeliveryController(DeliveryService s,@Value("${delivery.internal-key}") String k){service=s;internalKey=k;}
 @PostMapping("/internal/deliveries") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> create(@RequestHeader("X-Internal-Key") String token,@Valid @RequestBody NewDelivery d){check(token);if((d.deliveryLatitude()==null)!=(d.deliveryLongitude()==null))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Both destination coordinates are required together");if(d.smsOptIn()&&(d.customerPhone()==null||!d.customerPhone().matches("^\\+[1-9]\\d{7,14}$")))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"A valid E.164 phone number is required for opted-in SMS");return service.create(d.orderId(),d.userId(),d.customerEmail(),d.customerPhone(),d.smsOptIn(),d.deliveryAddress(),d.totalAmount(),d.deliveryLatitude(),d.deliveryLongitude(),d.items().stream().map(i->new DeliveryService.ItemInput(i.itemName(),i.quantity())).toList());}
 @PutMapping("/drivers/presence")public Map<String,Object> presence(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Presence p){role(jwt,"ROLE_DRIVER");return service.presence(uid(jwt),p.latitude(),p.longitude(),p.available());}
 @GetMapping("/drivers/orders/available") public Map<String,Object> available(@AuthenticationPrincipal Jwt jwt){role(jwt,"ROLE_DRIVER");var rows=service.available();return Map.of("content",rows,"totalElements",rows.size());}
 @GetMapping("/drivers/orders/me") public Map<String,Object> mine(@AuthenticationPrincipal Jwt jwt){role(jwt,"ROLE_DRIVER");var rows=service.mine(uid(jwt));return Map.of("content",rows,"totalElements",rows.size());}
 @PostMapping("/drivers/orders/{id}/accept") public Map<String,Object> accept(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){role(jwt,"ROLE_DRIVER");try{return service.accept(id,uid(jwt));}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.CONFLICT,e.getMessage(),e);}}
 @PostMapping("/drivers/location") public Map<String,Object> location(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Location x){role(jwt,"ROLE_DRIVER");try{return service.location(x.orderId(),uid(jwt),x.latitude(),x.longitude());}catch(SecurityException e){throw new ResponseStatusException(HttpStatus.FORBIDDEN,e.getMessage(),e);}}
 @GetMapping("/orders/{id}/driver-location") public Map<String,Object> driverLocation(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var d=service.get(id);String r=jwt.getClaimAsString("role");if(!Objects.equals(((Number)d.get("userId")).longValue(),uid(jwt))&&!("ROLE_DRIVER".equals(r)&&service.assigned(id,uid(jwt)))&&!("ROLE_ADMIN".equals(r)||"ROLE_RESTAURANT_OWNER".equals(r)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Cannot access this order location");return service.location(id);}
 @PutMapping("/orders/{id}/status") public Map<String,Object> status(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,String> body){String next=body.get("status"),r=jwt.getClaimAsString("role");if(next==null||!Set.of("ACCEPTED","PREPARING","READY","DELIVERED","CANCELLED").contains(next))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid delivery status");if("ROLE_DRIVER".equals(r)){if(!"DELIVERED".equals(next)||!service.assigned(id,uid(jwt)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Driver cannot set this status");}else{role(jwt,"ROLE_RESTAURANT_OWNER","ROLE_ADMIN");if("ROLE_RESTAURANT_OWNER".equals(r)){if(!service.ownerCanManage(id,uid(jwt)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"You do not own this order's restaurant");if(!Set.of("ACCEPTED","PREPARING","READY").contains(next))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Restaurant owners cannot set this status");}}return service.status(id,next);}
 @GetMapping("/notifications") public Map<String,Object> notifications(@AuthenticationPrincipal Jwt jwt){var rows=service.notifications(uid(jwt));return Map.of("content",rows,"totalElements",rows.size(),"unreadCount",service.unreadCount(uid(jwt)));}
 @PutMapping("/notifications/{id}/read")@ResponseStatus(HttpStatus.NO_CONTENT)public void markRead(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){service.markNotificationRead(uid(jwt),id);}
 @PutMapping("/notifications/read-all")@ResponseStatus(HttpStatus.NO_CONTENT)public void markAllRead(@AuthenticationPrincipal Jwt jwt){service.markAllNotificationsRead(uid(jwt));}
 private void check(String token){if(!MessageDigest.isEqual(token.getBytes(StandardCharsets.UTF_8),internalKey.getBytes(StandardCharsets.UTF_8)))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid internal service token");}
 private long uid(Jwt jwt){return Long.parseLong(jwt.getClaim("userId").toString());}private void role(Jwt jwt,String... roles){if(Arrays.stream(roles).noneMatch(x->x.equals(jwt.getClaimAsString("role"))))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Insufficient role");}
 public record Item(@NotBlank String itemName,@Min(1) int quantity){} public record NewDelivery(@NotNull Long orderId,@NotNull Long userId,@Email @NotBlank String customerEmail,@Size(max=30) String customerPhone,boolean smsOptIn,@NotBlank String deliveryAddress,@NotNull BigDecimal totalAmount,@DecimalMin("-90") @DecimalMax("90") BigDecimal deliveryLatitude,@DecimalMin("-180") @DecimalMax("180") BigDecimal deliveryLongitude,@NotNull List<@Valid Item> items){} public record Location(@NotNull Long orderId,@DecimalMin("-90") @DecimalMax("90") BigDecimal latitude,@DecimalMin("-180") @DecimalMax("180") BigDecimal longitude){}public record Presence(@DecimalMin("-90")@DecimalMax("90")BigDecimal latitude,@DecimalMin("-180")@DecimalMax("180")BigDecimal longitude,boolean available){}
}
